CREATE     PROCEDURE [synapse_fo].[usp_Update_INVENTITEMGROUP]
AS
/*
	Created by: Raj Maddala
	Created on: 2023-05-15 10:30:43
	Description: Update stored procedure for INVENTITEMGROUP from synapse finops datalake to BI
*/
BEGIN
	UPDATE tgt SET 
		tgt.[ASSETGROUP_IN] = stg.[ASSETGROUP_IN],
		tgt.[DATAAREAID] = stg.[DATAAREAID],
		tgt.[DataLakeModified_DateTime] = stg.[DataLakeModified_DateTime],
		tgt.[DUEDATELIMITGROUPID_ES] = stg.[DUEDATELIMITGROUPID_ES],
		--tgt.[FileName] = stg.[FileName],
		tgt.[ITEMGROUPID] = stg.[ITEMGROUPID],
		tgt.[LastProcessedChange_DateTime] = stg.[LastProcessedChange_DateTime],
		tgt.[LOADTEMPLATEID] = stg.[LOADTEMPLATEID],
		--tgt.[LSN] = stg.[LSN],
		tgt.[MODIFIEDDATETIME] = stg.[MODIFIEDDATETIME],
		tgt.[NAME] = stg.[NAME],
		tgt.[PARTITION] = stg.[PARTITION],
		tgt.[RECID] = stg.[RECID],
		tgt.[RECVERSION] = stg.[RECVERSION],
		tgt.[RETAILSAFTSTANDARDVATCODE] = stg.[RETAILSAFTSTANDARDVATCODE],
		tgt.[REVRECDEFAULTREVENUERECOGNITIONSCHEDULE] = stg.[REVRECDEFAULTREVENUERECOGNITIONSCHEDULE],
		tgt.[REVRECEXCLUDEFROMCARVEOUT] = stg.[REVRECEXCLUDEFROMCARVEOUT],
		tgt.[REVRECMEDIANPRICE] = stg.[REVRECMEDIANPRICE],
		tgt.[REVRECMEDIANPRICEMAXIMUMTOLERANCE] = stg.[REVRECMEDIANPRICEMAXIMUMTOLERANCE],
		tgt.[REVRECMEDIANPRICEMINIMUMTOLERANCE] = stg.[REVRECMEDIANPRICEMINIMUMTOLERANCE],
		tgt.[REVRECREVENUERECOGNITIONENABLED] = stg.[REVRECREVENUERECOGNITIONENABLED],
		tgt.[REVRECREVENUETYPE] = stg.[REVRECREVENUETYPE],
		tgt.[STANDARDITEMALLOCATEID] = stg.[STANDARDITEMALLOCATEID],
		--tgt.[SysRowId] = stg.[SysRowId],
		tgt.[TAXITEMGROUPIDPURCH] = stg.[TAXITEMGROUPIDPURCH],
		tgt.[TAXITEMGROUPIDSALES] = stg.[TAXITEMGROUPIDSALES]
	 FROM [synapse_fo].[INVENTITEMGROUP] tgt
		INNER JOIN [staging_fo].[INVENTITEMGROUP] stg
			ON  stg.[DataAreaId] = tgt.[DataAreaId] 
			AND stg.[ItemGroupId] = tgt.[ItemGroupId] 
			AND stg.[PARTITION] = tgt.[PARTITION] 
		
END
